function config({ url, spreadsheetId, sheetName }) {
  if (
    typeof url !== "string" ||
    !/^https:\/\/[a-zA-Z0-9](?:[a-zA-Z0-9.-]*[a-zA-Z0-9])?(?:\/[a-zA-Z0-9._~!$&'()*+,;=:@%/-]*)?$/.test(
      url,
    ) ||
    url.includes("YOUR_")
  )
    throw Error("Configure the HTTPS public Squarespace collection URL without query parameters");
  if (
    typeof spreadsheetId !== "string" ||
    !spreadsheetId.trim() ||
    spreadsheetId.startsWith("YOUR_") ||
    typeof sheetName !== "string" ||
    !sheetName.trim() ||
    /[!\r\n]/.test(sheetName)
  )
    throw Error("Configure the spreadsheet and sheet");
  const q = "'" + sheetName.replace(/'/g, "''") + "'";
  return { url, spreadsheetId, sheetName, range: q + "!A:ZZZ" };
}

return [
  {
    json: config({
      url: "https://YOUR_SQUARESPACE_DOMAIN/blog",
      spreadsheetId: "YOUR_SPREADSHEET_ID",
      sheetName: "Articles",
    }),
  },
];

function plan({ items, values, sheetName }) {
  if (
    !Array.isArray(items) ||
    !Array.isArray(values) ||
    !values.length ||
    !Array.isArray(values[0])
  )
    throw Error("The sheet needs headers");
  const h = values[0],
    fields = [
      "id",
      "tags",
      "title",
      "urlId",
      "addedOn",
      "fullUrl",
      "assetUrl",
      "publishOn",
      "categories",
    ];
  if (fields.some((x) => h.indexOf(x) < 0 || h.indexOf(x) !== h.lastIndexOf(x)))
    throw Error("The sheet needs unique required headers");
  const indexes = Object.fromEntries(fields.map((x) => [x, h.indexOf(x)])),
    existing = new Map();
  for (let i = 1; i < values.length; i++) {
    let row = values[i];
    if (!Array.isArray(row)) throw Error("Invalid sheet row");
    let id = row[indexes.id];
    if (id === null || id === undefined || id === "") continue;
    if (typeof id !== "string" || existing.has(id)) throw Error("Duplicate or invalid sheet ID");
    existing.set(id, { index: i + 1, raw: row });
  }
  const seen = new Set(),
    date = (v) => {
      if (
        (typeof v !== "number" && typeof v !== "string") ||
        v === "" ||
        !Number.isFinite(new Date(v).getTime())
      )
        throw Error("Invalid collection date");
      return new Date(v).toISOString().slice(0, 10);
    },
    tasks = [];
  let appendIndex = values.length + 1;
  for (const item of items) {
    if (!item || typeof item.id !== "string" || !item.id || seen.has(item.id))
      throw Error("Invalid or duplicate collection ID");
    seen.add(item.id);
    for (const key of ["title", "urlId", "fullUrl"])
      if (typeof item[key] !== "string") throw Error("Missing collection field");
    for (const key of ["tags", "categories"])
      if (!Array.isArray(item[key]) || item[key].some((x) => typeof x !== "string"))
        throw Error("Invalid collection tags");
    if (item.assetUrl != null && typeof item.assetUrl !== "string")
      throw Error("Invalid image URL");
    const fieldsValue = {
        id: item.id,
        tags: item.tags.join(", "),
        title: item.title,
        urlId: item.urlId,
        addedOn: date(item.addedOn),
        fullUrl: item.fullUrl,
        assetUrl: item.assetUrl ?? "",
        publishOn: date(item.publishOn),
        categories: item.categories.join(", "),
      },
      target = existing.get(item.id) ?? { index: appendIndex++, raw: [] };
    tasks.push({ id: item.id, index: target.index, raw: target.raw, indexes, fieldsValue });
  }
  return { tasks, sheetName };
}

const c = $("Configure the collection and sheet").first().json,
  pages = $("Read collection pages")
    .all()
    .map((x) => x.json);
const seen = new Set();
for (let i = 0; i < pages.length; i++) {
  const q = pages[i]?.pagination;
  if (
    !Array.isArray(pages[i]?.items) ||
    !q ||
    typeof q.nextPage !== "boolean" ||
    q.nextPage !== i < pages.length - 1
  )
    throw Error("Collection pagination incomplete");
  if (q.nextPage) {
    if (
      !Number.isSafeInteger(q.nextPageOffset) ||
      q.nextPageOffset < 0 ||
      seen.has(q.nextPageOffset)
    )
      throw Error("Invalid or repeated collection offset");
    seen.add(q.nextPageOffset);
  }
}
const p = plan({
  items: pages.flatMap((x) => x.items),
  values: $input.first().json.values ?? [],
  sheetName: c.sheetName,
});
return p.tasks.map((json) => ({ json }));

function update({ item, checked, sheetName }) {
  if (
    !Array.isArray(checked) ||
    checked.length > 1 ||
    JSON.stringify(checked[0] ?? []) !== JSON.stringify(item.raw)
  )
    throw Error("Sheet row changed since reading");
  const q = "'" + sheetName.replace(/'/g, "''") + "'",
    col = (n) => {
      let x = n + 1,
        s = "";
      while (x) {
        x--;
        s = String.fromCharCode(65 + (x % 26)) + s;
        x = Math.floor(x / 26);
      }
      return s;
    };
  return {
    data: Object.entries(item.fieldsValue).map(([key, v]) => ({
      range: q + "!" + col(item.indexes[key]) + item.index,
      values: [[v]],
    })),
  };
}

const c = $("Configure the collection and sheet").first().json;
return [
  {
    json: update({
      item: $("Process articles one at a time").item.json,
      checked: $input.first().json.values ?? [],
      sheetName: c.sheetName,
    }),
  },
];
